<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {UploadCloud,RotateCcw,Play,Copy,Download,ArrowUp,ArrowDown} from 'lucide-vue-next';
const props=defineProps({tool:Object,en:Boolean});const tr=(zh,en)=>props.en?en:zh;
const files=ref([]),options=ref({}),error=ref(''),busy=ref(false),done=ref(false),result=ref(''),preview=ref(''),source=ref(''),info=ref(''),copied=ref(false),fileInput=ref(null),bytes=ref(null),extension=ref(''),mime=ref('');
let ticket=0,worker,ready,pending,qrReader,timer;const pdf=computed(()=>props.tool.id.startsWith('pdf-'));const image=computed(()=>props.tool.id.startsWith('image-')||props.tool.id==='qr-read');
function invalidate(){ticket++;busy.value=false;done.value=false;result.value='';bytes.value=null;error.value='';copied.value=false;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
function reset(){invalidate();files.value=[];if(source.value)URL.revokeObjectURL(source.value);source.value='';info.value='';options.value=Object.fromEntries(props.tool.fields.map(f=>[f.key,f.value]));if(fileInput.value)fileInput.value.value='';}
function fail(){error.value=pdf.value?tr('请检查 PDF 是否完整、未加密，页码是否存在。合并需要至少两份文件。','Check that PDFs are complete and unencrypted and page numbers exist. Merging needs at least two files.'):image.value?tr('请检查图片是否有效、裁剪范围是否在原图内。二维码需清晰完整；输出尺寸须在限制内。','Check image validity, crop bounds, QR clarity and output dimension limits.'):tr('请先选择符合大小限制的文件，再重试。','Choose a file within the size limit, then retry.');}
function select(event){invalidate();const selected=Array.from(event.target.files||[]);if(source.value)URL.revokeObjectURL(source.value);source.value='';info.value='';files.value=selected;const limit=props.tool.id==='file-base64'?5:image.value?25:50;if(!selected.length)return;if(selected.length>20||selected.reduce((n,f)=>n+f.size,0)>limit*1024*1024){files.value=[];error.value=tr(`文件总大小不能超过 ${limit} MB，最多 20 个。`,`Files must total ≤${limit} MB, with at most 20 files.`);return;}if(image.value){if(!selected[0].type.match(/^image\/(png|jpeg|webp)$/)){files.value=[];fail();return;}source.value=URL.createObjectURL(selected[0]);const current=ticket;const img=new Image();img.onload=()=>{if(ticket===current)info.value=`${img.naturalWidth} × ${img.naturalHeight} px`;};img.src=source.value;}}
function reorder(index,delta){const next=index+delta;if(next<0||next>=files.value.length)return;invalidate();const a=[...files.value];[a[index],a[next]]=[a[next],a[index]];files.value=a;}
function startWorker(){if(ready)return ready;ready=new Promise((resolve,reject)=>{worker=new Worker(new URL('./pdf-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.ready)resolve();else if(pending){const p=pending;pending=null;clearTimeout(p.timer);data.error?p.reject(Error(data.error)):p.resolve(data.bytes)}};worker.onerror=()=>{reject(Error('worker'));if(pending){clearTimeout(pending.timer);pending.reject(Error('worker'));pending=null;}worker?.terminate();ready=null;};});return ready;}
async function pdfProcess(buffers){await startWorker();if(pending)throw Error('busy');return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{pending=null;worker.terminate();ready=null;reject(Error('timeout'));},30000);pending={resolve,reject,timer:timeout};worker.postMessage({id:props.tool.id,files:buffers,pages:String(options.value.pages||'').replace(/\s/g,'')});});}
async function run(){if(busy.value)return;invalidate();const current=ticket;busy.value=true;try{const id=props.tool.id;if(!files.value.length||id==='pdf-merge'&&files.value.length<2)throw Error('file');let data=null,text='';let ext='',type='';if(pdf.value){const buffers=await Promise.all(files.value.map(f=>f.arrayBuffer()));if(buffers.some(b=>!new TextDecoder().decode(b.slice(0,1024)).includes('%PDF-')))throw Error('pdf');data=await pdfProcess(buffers);ext='pdf';type='application/pdf';}
 else if(id==='file-hash'){const hash=await crypto.subtle.digest('SHA-256',await files.value[0].arrayBuffer());text=Array.from(new Uint8Array(hash),x=>x.toString(16).padStart(2,'0')).join('');ext='txt';type='text/plain';}
 else if(id==='file-base64'){const file=files.value[0];text=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});ext='txt';type='text/plain';}
 else {const img=new Image();img.src=source.value;await img.decode();const w=img.naturalWidth,h=img.naturalHeight;if(w*h>40000000)throw Error('image-size');const canvas=document.createElement('canvas');let x=0,y=0,sw=w,sh=h;canvas.width=w;canvas.height=h;if(id==='image-crop'){x=Number(options.value.x);y=Number(options.value.y);sw=Number(options.value.width);sh=Number(options.value.height);if(![x,y,sw,sh].every(Number.isInteger)||x<0||y<0||sw<1||sh<1||x+sw>w||y+sh>h)throw Error('crop');canvas.width=sw;canvas.height=sh;}
 if(id==='image-resize'){const width=Number(options.value.width);if(!Number.isInteger(width)||width<1)throw Error('size');canvas.width=width;canvas.height=Math.max(1,Math.round(h*width/w));}
 if(id!=='qr-read'&&(canvas.width>8192||canvas.height>8192||canvas.width*canvas.height>16000000))throw Error('output-size');if(id==='qr-read'&&w*h>16000000)throw Error('qr-size');
 const ctx=canvas.getContext('2d');const format=id==='image-convert'?options.value.format:'png';if(!['png','jpeg','webp'].includes(format))throw Error('format');if(format==='jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height)}ctx.drawImage(img,x,y,sw,sh,0,0,canvas.width,canvas.height);
 if(id==='qr-read'){const reader=await(qrReader??=import('jsqr'));const pixels=ctx.getImageData(0,0,w,h);const decoded=reader.default(pixels.data,w,h);if(!decoded)throw Error('qr');text=decoded.data;ext='txt';type='text/plain';}else{type='image/'+format;const blob=await new Promise(resolve=>canvas.toBlob(resolve,type,.9));if(!blob||blob.type!==type)throw Error('format');data=new Uint8Array(await blob.arrayBuffer());ext=format==='jpeg'?'jpg':format;}}
 if(current!==ticket)return;result.value=text;bytes.value=data;extension.value=ext;mime.value=type;done.value=true;if(type.startsWith('image/'))preview.value=URL.createObjectURL(new Blob([data],{type}));}catch{if(current===ticket)fail();}finally{if(current===ticket)busy.value=false;}}
function download(){const url=URL.createObjectURL(new Blob([bytes.value??result.value],{type:mime.value}));const a=document.createElement('a');a.href=url;a.download=`toolbox-${props.tool.id}.${extension.value}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(){try{await navigator.clipboard.writeText(result.value);copied.value=true;clearTimeout(timer);timer=setTimeout(()=>copied.value=false,2000)}catch{error.value=tr('复制失败，请手动选择结果复制。','Copy failed. Select and copy the result manually.');}}
watch(()=>props.tool.id,reset);onMounted(()=>{reset();if(pdf.value)startWorker().catch(fail);if(props.tool.id==='qr-read')qrReader=import('jsqr');});onUnmounted(()=>{ticket++;worker?.terminate();if(pending)clearTimeout(pending.timer);clearTimeout(timer);if(source.value)URL.revokeObjectURL(source.value);if(preview.value)URL.revokeObjectURL(preview.value)});
</script>
<template><section class="editor-panel file-tool"><div class="editor-toolbar"><strong>{{tr('开始使用','Your workspace')}}</strong><button @click="reset"><RotateCcw :size="15"/>{{tr('重置','Reset')}}</button></div><label class="upload-area"><UploadCloud :size="36"/><strong>{{tr('点击选择文件','Click to choose files')}}</strong><span>{{pdf?'PDF':image?'JPG / PNG / WebP':tr('任意文件','Any file')}} · {{tr('大小限制见上方说明','See size limits above')}}</span><input ref="fileInput" class="native-file-input" type="file" :multiple="tool.id==='pdf-merge'" :accept="pdf?'.pdf':image?'image/png,image/jpeg,image/webp':undefined" :aria-label="tr('选择文件','Choose files')" @change="select" :disabled="busy"></label><ol v-if="files.length" class="selected-files"><li v-for="(file,i) in files" :key="i"><span>{{file.name}} · {{(file.size/1024).toFixed(1)}} KB</span><template v-if="tool.id==='pdf-merge'"><button :disabled="i===0||busy" :aria-label="tr('上移文件','Move file up')" @click="reorder(i,-1)"><ArrowUp :size="18"/></button><button :disabled="i===files.length-1||busy" :aria-label="tr('下移文件','Move file down')" @click="reorder(i,1)"><ArrowDown :size="18"/></button></template></li></ol><p v-if="info">{{info}}</p><img v-if="source" :src="source" class="source-preview" :alt="tr('原图预览','Original preview')"><div v-if="tool.fields.length" class="tool-options"><label v-for="field in tool.fields" :key="field.key">{{field.label[en?1:0]}}<select v-if="field.type==='select'" :data-option="field.key" v-model="options[field.key]" @change="invalidate" :disabled="busy"><option v-for="choice in field.choices" :key="choice[0]" :value="choice[0]">{{choice[en?2:1]}}</option></select><input v-else :data-option="field.key" v-model="options[field.key]" :type="field.type" @input="invalidate" :disabled="busy"></label></div><button class="primary run-button" :disabled="busy" :aria-busy="busy" @click="run"><Play :size="16"/>{{busy?tr('正在处理…','Processing…'):tr('开始处理','Process files')}}</button><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="done" class="output"><img v-if="preview" :src="preview" class="source-preview" :alt="tr('处理结果','Result')"><label v-if="!bytes" class="input-label">{{tr('处理结果','Result')}}<textarea :value="result" readonly rows="7"/></label><p v-if="bytes">{{(bytes.length/1024).toFixed(1)}} KB · {{mime}}</p><p class="result-feedback" role="status">{{tr('处理完成，可以下载结果。','Done. Your result is ready to download.')}}</p><div class="result-actions"><button v-if="!bytes" @click="copy"><Copy :size="16"/>{{copied?tr('已复制','Copied'):tr('复制结果','Copy result')}}</button><button @click="download"><Download :size="16"/>{{tr('下载结果','Download result')}}</button></div></div></section></template>
